var results=new System.Collections.Generic.List<object>();var old=UnityEngine.RenderTexture.active;var scene=UnityEditor.SceneManagement.EditorSceneManager.NewPreviewScene();var root=new UnityEngine.GameObject("Art parity proof");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,scene);var camGo=new UnityEngine.GameObject("Proof camera");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(camGo,scene);var camera=camGo.AddComponent<UnityEngine.Camera>();camera.orthographic=true;camera.orthographicSize=8;camera.transform.position=new UnityEngine.Vector3(8,8,-10);camera.clearFlags=UnityEngine.CameraClearFlags.SolidColor;camera.backgroundColor=UnityEngine.Color.clear;camera.scene=scene;camera.allowHDR=false;camera.allowMSAA=false;var rt=new UnityEngine.RenderTexture(512,512,0,UnityEngine.RenderTextureFormat.ARGB32,UnityEngine.RenderTextureReadWrite.sRGB);rt.Create();camera.targetTexture=rt;var read=new UnityEngine.Texture2D(512,512,UnityEngine.TextureFormat.RGBA32,false);var source=new UnityEngine.Texture2D(2,2);var renderer=root.AddComponent<ANIMOL.Gameplay.FreeShapeTerrainRenderer>();System.IO.Directory.CreateDirectory("Docs/Validation/FreeShapePolish");try{foreach(var style in new[]{"T01_A","T01_B","T01_C","T01_D"}){var layer=new Animol.TerrainStructure.FreeShapeLayer();for(int y=0;y<16;y++)for(int x=0;x<16;x++)layer.cells.Add(new Animol.TerrainStructure.FreeShapeCell{x=x,y=y,styleId=style});renderer.Rebuild(layer,1);camera.Render();UnityEngine.RenderTexture.active=rt;read.ReadPixels(new UnityEngine.Rect(0,0,512,512),0,0);read.Apply();System.IO.File.WriteAllBytes("Docs/Validation/FreeShapePolish/Unity-"+style+".png",read.EncodeToPNG());source.LoadImage(System.IO.File.ReadAllBytes("Tools/ArtSources/ANIMOL_FreeShape_Sprites_v1/Samples/"+style+"/maximum_rectangle_16x16.png"));var a=read.GetPixels32();var b=source.GetPixels32();int rgb=0,alpha=0;for(int i=0;i<a.Length;i++){if(a[i].a!=b[i].a)alpha++;if(a[i].a!=0&&b[i].a!=0&&(a[i].r!=b[i].r||a[